n of the Ring", ["quest:2962"] = "The Only Cure is More Green Glow", ["zone:1416"] = "Alterac Mountains", ["zone:1426"] = "Dun Morogh", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge", ["zone:1457"] = "Darnassus" },
